1	import { mkdir, mkdtemp, readFile, writeFile } from 'node:fs/promises';
2	import { tmpdir } from 'node:os';
3	import * as path from 'pathe';
4	import { describe, expect, test } from 'vitest';
5	import {
6		craEntryDocument,
7		craProcessEnvironmentDefines,
8		craPublicAssetPaths,
9		createCraPublicDirectoryPlugin,
10		createCraTildeCssImportPlugin,
11		createCraViteAdapter,
12		rewriteWebpackTildeCssImports,
13		substituteCraTemplatePlaceholders,
14	} from '../src/react-cra-vite-adapter.ts';
15	
16	const template = [
17		'<!DOCTYPE html>',
18		'<html lang="en">',
19		'  <head>',
20		'    <link rel="icon" href="%PUBLIC_URL%/logo.svg" />',
21		'    <script src="https://example.invalid/tag?id=%REACT_APP_ANALYTICS_ID%"></script>',
22		'  </head>',
23		'  <body>',
24		'    <div id="root"></div>',
25		'  </body>',
26		'</html>',
27		'',
28	].join('\n');
29	
30	describe('create-react-app template placeholders', () => {
31		test('substitutes provided keys and preserves unknown placeholders', () => {
32			const result = substituteCraTemplatePlaceholders(template, { PUBLIC_URL: '' });
33			expect(result).toContain('href="/logo.svg"');
34			expect(result).toContain('id=%REACT_APP_ANALYTICS_ID%');
35		});
36		test('honours a non-root public url for every occurrence', () => {
37			const result = substituteCraTemplatePlaceholders(
38				'%PUBLIC_URL%/a %PUBLIC_URL%/b',
39				{ PUBLIC_URL: '/console' },
40			);
41			expect(result).toBe('/console/a /console/b');
42		});
43		test('injects the entry module before the closing body tag', () => {
44			const document = craEntryDocument({
45				template,
46				entryModule: '/src/index.tsx',
47				environment: { PUBLIC_URL: '' },
48			});
49			const script = '<script type="module" src="/src/index.tsx"></script>';
50			expect(document).toContain(script);
51			expect(document.indexOf(script)).toBeLessThan(document.indexOf('</body>'));
52			expect(document.indexOf('<div id="root">')).toBeLessThan(document.indexOf(script));
53			expect(craEntryDocument({ template, entryModule: '/src/index.tsx' })).toContain(
54				'%PUBLIC_URL%/logo.svg',
55			);
56		});
57		test('appends the entry module when no body tag is present', () => {
58			const document = craEntryDocument({ template: '<div id="root"></div>', entryModule: '/main.js' });
59			expect(document).toBe('<div id="root"></div>\n<script type="module" src="/main.js"></script>\n');
60		});
61	});
62	
63	describe('create-react-app process environment defines', () => {
64		test('inlines each key and the whole environment in sorted order', () => {
65			const defines = craProcessEnvironmentDefines({
66				PUBLIC_URL: '',
67				NODE_ENV: 'production',
68				REACT_APP_API: 'https://example.invalid',
69			});
70			expect(defines['process.env.NODE_ENV']).toBe('"production"');
71			expect(defines['process.env.PUBLIC_URL']).toBe('""');
72			expect(defines['process.env.REACT_APP_API']).toBe('"https://example.invalid"');
73			expect(defines['process.env']).toBe(
74				'{"NODE_ENV":"production","PUBLIC_URL":"","REACT_APP_API":"https://example.invalid"}',
75			);
76			expect(craProcessEnvironmentDefines({})).toEqual({ 'process.env': '{}' });
77		});
78	});
79	
80	describe('webpack tilde specifiers in CSS', () => {
81		test('rewrites quoted and url() imports without touching relative ones', () => {
82			const code = [
83				"@import '~antd/dist/antd.css';",
84				'@import "~normalize.css";',
85				'@import url("~a-package/b.css");',
86				"@import './local.css';",
87			].join('\n');
88			expect(rewriteWebpackTildeCssImports(code)).toBe(
89				[
90					"@import 'antd/dist/antd.css';",
91					'@import "normalize.css";',
92					'@import url("a-package/b.css");',
93					"@import './local.css';",
94				].join('\n'),
95			);
96		});
97		test('the plugin transforms only CSS ids and returns null when unchanged', () => {
98			const plugin = createCraTildeCssImportPlugin();
99			expect(plugin.enforce).toBe('pre');
100			expect(plugin.transform("@import '~antd/dist/antd.css';", '/app/src/App.css?used')).toEqual({
101				code: "@import 'antd/dist/antd.css';",
102				map: null,
103			});
104			expect(plugin.transform("@import '~antd/dist/antd.css';", '/app/src/App.tsx')).toBeNull();
105			expect(plugin.transform("@import './local.css';", '/app/src/App.css')).toBeNull();
106		});
107	});
108	
109	describe('create-react-app public directory', () => {
110		test('copies every public file except the template into the build output', async () => {
111			const root = await mkdtemp(path.join(tmpdir(), 'versionless-cra-public-'));
112			const publicDirectory = path.join(root, 'public');
113			const outDir = path.join(root, 'build');
114			await mkdir(path.join(publicDirectory, 'nested'), { recursive: true });
115			await mkdir(outDir, { recursive: true });
116			await writeFile(path.join(publicDirectory, 'index.html'), 'template');
117			await writeFile(path.join(publicDirectory, 'robots.txt'), 'User-agent: *\n');
118			await writeFile(path.join(publicDirectory, 'nested/widget.js'), 'export {};\n');
119	
120			expect(await craPublicAssetPaths(publicDirectory, ['index.html'])).toEqual([
121				'nested/widget.js',
122				'robots.txt',
123			]);
124	
125			const plugin = createCraPublicDirectoryPlugin({
126				directory: publicDirectory,
127				exclude: ['index.html'],
128			});
129			plugin.configResolved({ build: { outDir } });
130			await plugin.closeBundle.handler();
131			expect(await readFile(path.join(outDir, 'robots.txt'), 'utf8')).toBe('User-agent: *\n');
132			expect(await readFile(path.join(outDir, 'nested/widget.js'), 'utf8')).toBe('export {};\n');
133			await expect(readFile(path.join(outDir, 'index.html'), 'utf8')).rejects.toThrow();
134		});
135		test('refuses to copy before the build output directory is resolved', async () => {
136			const plugin = createCraPublicDirectoryPlugin({ directory: tmpdir() });
137			await expect(plugin.closeBundle.handler()).rejects.toThrow('outDir is unresolved');
138		});
139		test('the composed adapter excludes the template by default', () => {
140			const [transform, output] = createCraViteAdapter({ publicDirectory: tmpdir() });
141			expect(transform.name).toBe('versionless-cra-tilde-css-import');
142			expect(output.name).toBe('versionless-cra-public-directory');
143			expect(output.closeBundle.order).toBe('post');
144		});
145	});
