import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, rmSync, renameSync, existsSync } from 'node:fs';
import * as path from 'node:path';

export const canon = (v) =>
	v === null || typeof v !== 'object'
		? (JSON.stringify(v) ?? 'null')
		: Array.isArray(v)
			? '[' + v.map(canon).join(',') + ']'
			: '{' +
				Object.keys(v)
					.sort()
					.map((k) => JSON.stringify(k) + ':' + canon(v[k]))
					.join(',') +
				'}';

export function inventory(root) {
	const files = [];
	(function walk(d) {
		for (const e of readdirSync(d, { withFileTypes: true }).sort((a, b) =>
			a.name < b.name ? -1 : 1,
		)) {
			const p = path.join(d, e.name);
			if (e.isDirectory()) walk(p);
			else files.push(p);
		}
	})(root);
	const entries = files
		.map((f) => path.relative(root, f).split(path.sep).join('/'))
		.sort((a, b) => (a === b ? 0 : a < b ? -1 : 1))
		.map((p) => ({
			path: p,
			sha256: createHash('sha256').update(readFileSync(path.join(root, p))).digest('hex'),
		}));
	return { digest: createHash('sha256').update(canon(entries)).digest('hex'), files: entries };
}

export function rotate(from, to) {
	if (existsSync(to)) rmSync(to, { recursive: true, force: true });
	renameSync(from, to);
}

